package android.content;
import java.io.*;public class Context {public static final int MODE_PRIVATE=0;public static final String CLIPBOARD_SERVICE="clipboard";public Context application=this;public final File directory;public final ClipboardManager clipboard=new ClipboardManager();public boolean failWrite;public int writes,serviceReads;public Context(File f){directory=f;}public Context getApplicationContext(){return application;}public Object getSystemService(String service){serviceReads++;return clipboard;}public FileOutputStream openFileOutput(String name,int mode)throws FileNotFoundException {writes++;if(failWrite)throw new FileNotFoundException("synthetic-private-storage-error");directory.mkdirs();return new FileOutputStream(new File(directory,name));}}
